  t('<b>Five reasons</b>', '<b>E</b>qual vote value', '<b>D</b>emographic shifts (migration, urbanisation)', '<b>F</b>air regional representation', '<b>S</b>trengthens democracy, trust', '<b>P</b>revents <b>gerrymandering</b>', w=22),
