  bx('ye', '<b>Handout alert:</b> State Executive Committee chair appears as ex-officio member and as ex-officio CEO: one person, both roles. <b>LK differs:</b> chair + other members not over 9, SEC chair ex-officio and nominated members not over <b>8</b> (by CM). Use handout; remember LK’s 8.'),
  t('<b>SDMA functions</b>', t('<b>Policy, planning</b>', 'State Policy per National Policy', 'approve <b>SDMP</b>', 'approve Departmental plans', 'DRR in State development'), t('<b>Coordination</b>', 'implement SDMP', 'recommend mitigation funds', 'oversee State Executive Committee'), t('<b>Monitoring</b>', 'review departmental, district plans (LK: development plans too)', 'monitor capacity and preparedness', 'guidelines for prevention'), '<b>Annual Report</b> to State Govt, laid before <b>State Legislature</b>', w=26),
  mn('P-D', '“<b>P</b>lans <b>D</b>own the line”: State policy, SDMP, Departmental plans.'),
